#[cfg(test)]
mod tests {
    #[test]
    fn pbr_dispatch_matches_compiler_payload_and_descriptor_capture() {
        let vs = include_str!("vertex_TRUEOS_VS_state_v1.txt");
        let ps = include_str!("fragment_TRUEOS_PS_state_v1.txt");
        let bindings = include_str!("02_fragment_00_TRUEOS_HelioC_bind_map.txt");
        assert!(vs.contains("urb_read_length=2 urb_entry_64b=2 vue_slots=6"));
        assert!(ps.contains("grf_start8=4 grf_start16=6 "));
        assert!(bindings.contains("surfaces=9 samplers=1"));
        assert!(bindings.contains("surface[8]=set:0 binding:9 "));
        let pipeline = super::pipeline();
        assert_eq!(pipeline.vs.meta.kernel.grf_start_register, 2);
        assert_eq!(pipeline.ps.meta.kernel.grf_start_register, 6);
        assert_eq!(pipeline.ps.meta.num_varying_inputs, 4);
        assert_eq!(pipeline.ps.meta.kernel.binding_table_entry_count, 9);
        assert_eq!(pipeline.vs.code.len() * 4, pipeline.vs.meta.kernel.code_size_bytes as usize);
        assert_eq!(pipeline.ps.code.len() * 4, pipeline.ps.meta.kernel.code_size_bytes as usize);
    }
}
